#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' # 100km due north and due east of Raleigh
#' raleigh <- ga_point(c(-78.6382, -78.6382), c(35.7796, 35.7796))
