ga_dest_rhumb <- function(origin, bearing, distance) .Call(wrap__ga_dest_rhumb, origin, bearing, distance)

#' @export
#' @rdname destination
ga_dest_euclidean <- function(origin, bearing, distance) .Call(wrap__ga_dest_euclidean, origin, bearing, distance)

#' @export
