#'   matrix(c(0, 0, 1, 0, 1, 1, 0, 1, 0, 0), ncol = 2, byrow = TRUE)
#' ))
#' g <- geoarrow::as_geoarrow_array(sf::st_sfc(square))
#'
#' as.vector(ga_is_convex(g))
ga_is_convex <- function(geometry) .Call(wrap__ga_is_convex, geometry)

