#' @references [SimplifyVwIdx](https://docs.rs/geo/latest/geo/algorithm/simplify_vw/trait.SimplifyVwIdx.html)
ga_simplify_vw_idx <- function(geometry, epsilon) .Call(wrap__ga_simplify_vw_idx, geometry, epsilon)

#' Order rows along a Hilbert curve
#'
#' Returns the row order that puts geometries whose bounding box centres lie
#' close together next to each other. Pass it to `[` to sort an array or a
#' data frame so that nearby rows sit together.
#'
#' @details
#' `ga_hilbert_order()` maps each centre onto a 65536 by 65536 grid over the
#' extent of every row and orders the rows by their position along a Hilbert
#' curve through that grid, the same curve [RTree] packs its tree with. If you
#' sort a table this way before you write GeoParquet, each row group covers a
#' small area, so a reader can skip the row groups that cannot match a query.
#'
#' `ga_hilbert_order()` breaks ties by the original row order, and puts rows
#' with a null or empty geometry last, in their original order.
#'
#' @param geometry a GeoArrow geometry array
#' @returns an integer array of 1 based row numbers, the same length as
#'   `geometry`
#' @export
#' @family index
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' nc <- as.data.frame(read_shapefile(
#'   system.file("shape/nc.shp", package = "sf")
#' ))
#' ord <- as.vector(ga_hilbert_order(nc$geometry))
#' head(ord)
#'
#' # neighbouring counties now sit next to each other
#' head(nc[ord, "NAME"])
ga_hilbert_order <- function(geometry) .Call(wrap__ga_hilbert_order, geometry)

#' Order rows by sort-tile-recursive packing
#'
#' Returns the row order that sort-tile-recursive (STR) packing gives the
#' bounding box centres of `geometry`. Pass it to `[` to sort an array or a
#' data frame so that nearby rows sit together.
#'
#' @details
#' `ga_str_order()` sorts the rows by the x of their centres, cuts them into
#' vertical slices of `node_size` times the square root of the number of
#' leaves, and sorts each slice by y. That is the leaf order an STR packed
#' R-tree with `node_size` entries per node uses, the same packing
#' `RTree$new(sort = "str")` builds.
#'
#' `ga_str_order()` breaks ties by the original row order, and puts rows with
#' a null or empty geometry last, in their original order.
#'
#' @param geometry a GeoArrow geometry array
#' @param node_size how many rows share a leaf
#' @returns an integer array of 1 based row numbers, the same length as
#'   `geometry`
#' @export
#' @family index
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' nc <- as.data.frame(read_shapefile(
#'   system.file("shape/nc.shp", package = "sf")
#' ))
#' ord <- as.vector(ga_str_order(nc$geometry, node_size = 4))
#'
#' # the first slice runs south to north along the west of the state
#' head(nc[ord, "NAME"])
ga_str_order <- function(geometry, node_size = 16) .Call(wrap__ga_str_order, geometry, node_size)

#' Find which rows of `y` relate to each row of `x`
#'
#' Each function compares every row of `x` against every row of `y` and returns
#' the row numbers of `y` for which the named DE-9IM relationship holds. This is
#' the sparse form of the pairwise predicates in [ga_intersects()], and the
#' shape [ga_join()] needs.
#'
#' @details
#' These functions do not compare the full cross product. Each function indexes
#' `y` in a packed Hilbert R-tree and runs the relate test only on the rows
#' whose bounding boxes overlap, so the cost scales with the number of
#' candidates rather than with `length(x) * length(y)`.
#'
#' Each function returns a zero length element, not a null, for a row of `x`
#' that matches nothing. It returns a null element for a null or empty geometry
#' in `x`, and never returns one in `y`.
#'
#' [ga_disjoint()] has no sparse form. Disjointness is the one relationship you
#' cannot narrow with a bounding box, so the answer is almost every row of `y`
#' and the result is denser than the input.
#'
#' @param x a GeoArrow geometry array
#' @param y a GeoArrow geometry array
#' @returns a list array of 1 based row numbers into `y`, the same length as `x`
#' @export
#' @rdname sparse
#' @family topology
#' @references [Relate](https://docs.rs/geo/latest/geo/algorithm/relate/trait.Relate.html)
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' nc <- as.data.frame(read_shapefile(
#'   system.file("shape/nc.shp", package = "sf")
#' ))
#'
#' # which counties each county touches
#' nbrs <- as.vector(ga_sparse_touches(nc$geometry, nc$geometry))
#' nbrs[[1]]
#'
#' # how many neighbours each has
#' summary(lengths(nbrs))
ga_sparse_intersects <- function(x, y) .Call(wrap__ga_sparse_intersects, x, y)

#' @export
#' @rdname sparse
#' @family topology
ga_sparse_contains <- function(x, y) .Call(wrap__ga_sparse_contains, x, y)

#' @export
#' @rdname sparse
#' @family topology
ga_sparse_contains_properly <- function(x, y) .Call(wrap__ga_sparse_contains_properly, x, y)

#' @export
#' @rdname sparse
#' @family topology
ga_sparse_within <- function(x, y) .Call(wrap__ga_sparse_within, x, y)

#' @export
#' @rdname sparse
#' @family topology
ga_sparse_covers <- function(x, y) .Call(wrap__ga_sparse_covers, x, y)

#' @export
#' @rdname sparse
