#' @noRd
ga_sparse_dwithin_impl <- function(x, y, distance, metric) .Call(wrap__ga_sparse_dwithin_impl, x, y, distance, metric)

#' Find which rows of `y` are identical to each row of `x` within a tolerance
#'
#' Returns the row numbers of `y` that have the same type and structure as
#' each row of `x`, with every coordinate within `tolerance` of its
#' counterpart. This is the sparse form of [ga_equals_exact()], and matches
#' `sf::st_equals_exact()`.
#'
#' @details
#' `ga_sparse_equals_exact()` indexes `y` in a packed Hilbert R-tree and
#' compares only the rows whose bounding boxes come within `tolerance` of the
#' box of the row of `x`. It compares coordinates in order, so it does not
#' match a line to its reverse; use [ga_sparse_equals_topo()] for that.
#'
#' `ga_sparse_equals_exact()` returns a zero length element for a row of `x`
#' that matches nothing. It returns a null element for a null or empty
#' geometry in `x`, and for a `tolerance` that is `NA` or negative.
#'
#' @param x a GeoArrow geometry array
#' @param y a GeoArrow geometry array
#' @param tolerance the largest planar distance allowed between matching
#'   coordinates; length 1 or the same length as `x`
#' @returns a list array of 1 based row numbers into `y`, the same length as `x`
#' @export
#' @family topology
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' nc <- as.data.frame(read_shapefile(
#'   system.file("shape/nc.shp", package = "sf")
#' ))
#' shifted <- ga_translate(nc$geometry, 0.001, 0)
#'
#' # each county matches its shifted copy once the tolerance covers the shift
#' as.vector(ga_sparse_equals_exact(nc$geometry, shifted, 0))[1:3]
#' as.vector(ga_sparse_equals_exact(nc$geometry, shifted, 0.01))[1:3]
ga_sparse_equals_exact <- function(x, y, tolerance = 0) .Call(wrap__ga_sparse_equals_exact, x, y, tolerance)

#' Rows of `y` nearest each row of `x`, validated in R
#' @noRd
ga_sparse_knn_impl <- function(x, y, k, max_distance = NULL, metric) .Call(wrap__ga_sparse_knn_impl, x, y, k, max_distance, metric)

#' Expand a sparse predicate into the row pairs a join needs
#'
#' Turns the list of matches each sparse predicate returns into two columns,
#' one row per pair, which is the shape [ga_join()] takes and the shape a
#' database returns a spatial join in.
#'
#' @details
#' You can express everything but the padding with Arrow's own `list_flatten()`
#' and `list_parent_indices()`. What they cannot do is `left = TRUE`, where
#' `ga_sparse_pairs()` has to put back a row for each row of `x` that matched
#' nothing, so it does the whole expansion itself rather than leaving half to R.
#'
#' `ga_sparse_pairs()` numbers rows from 1, matching what the sparse predicates
#' return. It returns a row of `x` that matched nothing once with a null `y`
#' when `left = TRUE`, and drops it otherwise.
#'
#' @param hits a list array from one of the sparse predicates
#' @param left whether to keep the rows of `x` that matched nothing
#' @returns a struct array of `x` and `y` row numbers
#' @export
#' @family topology
#' @examplesIf requireNamespace("geoarrow", quietly = TRUE)
#' x <- ga_point(c(0, 5, 1), c(0, 5, 1))
#' y <- ga_point(c(0, 1), c(0, 1))
#'
#' # the middle row of x matches nothing, so you see it only with left = TRUE
#' ga_sparse_pairs(ga_sparse_intersects(x, y))
#' ga_sparse_pairs(ga_sparse_intersects(x, y), left = TRUE)
ga_sparse_pairs <- function(hits, left = FALSE) .Call(wrap__ga_sparse_pairs, hits, left)

#' Set the thread cap, from `options(geoarrowrs.thread_pool = )`
#'
#' geoarrowrs calls `ga_set_thread_pool()` on load and whenever you change the
#' option. With `0`, it returns the parallel paths to rayon's own default, which
#' is one thread per core.
#'
#' @param n the most threads to use, or `0` for rayon's default
#' @returns `n`, invisibly
#' @export
#' @family index
#' @examples
#' # hold the parallel paths to two threads
#' ga_set_thread_pool(2)
#'
#' # and back to one per core
#' ga_set_thread_pool(0)
ga_set_thread_pool <- function(n) .Call(wrap__ga_set_thread_pool, n)

#' Test a topological relationship
#'
#' Each function compares `x` and `y` row by row and returns `TRUE` when the
#' named DE-9IM relationship holds. These functions recycle `y` against `x`.
#'
#' @details
#' `ga_contains()` is `TRUE` when no point of `y` lies outside `x` and at least
#' one point of `y` lies in the interior of `x`. `ga_within()` is the same test
#' with the arguments swapped. `ga_covers()` and `ga_covered_by()` are the weaker
#' forms that allow every shared point to lie on the boundary.
#' `ga_contains_properly()` is the stricter form requiring `y` to fall entirely
#' within the interior.
#'
#' `ga_intersects()` and `ga_disjoint()` are negations of one another.
#' `ga_touches()` is `TRUE` when the geometries share a boundary point but no
#' interior point, `ga_crosses()` when their interiors meet in a lower dimension
#' than at least one of them, and `ga_overlaps()` when they meet in the same
#' dimension as both. `ga_equals_topo()` compares point sets rather than
#' coordinate order, so it still treats two geometries with different windings
#' as equal.
#'
#' Each function returns `NA` for a null geometry on either side.
#'
#' @param x a GeoArrow geometry array
#' @param y a GeoArrow geometry array; length 1 or the same length as `x`
#' @returns a boolean array of the same length as `x`
#' @export
#' @rdname topology
#' @family topology
#' @references [Relate](https://docs.rs/geo/latest/geo/algorithm/relate/trait.Relate.html)
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' big <- sf::st_polygon(list(
#'   matrix(c(0, 0, 4, 0, 4, 4, 0, 4, 0, 0), ncol = 2, byrow = TRUE)
#' ))
#' x <- geoarrow::as_geoarrow_array(sf::st_sfc(big))
#' y <- geoarrow::as_geoarrow_array(sf::st_sfc(sf::st_point(c(2, 2))))
#'
#' as.vector(ga_contains(x, y))
#' as.vector(ga_intersects(x, y))
ga_contains <- function(x, y) .Call(wrap__ga_contains, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_contains_properly <- function(x, y) .Call(wrap__ga_contains_properly, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_within <- function(x, y) .Call(wrap__ga_within, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_covers <- function(x, y) .Call(wrap__ga_covers, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_covered_by <- function(x, y) .Call(wrap__ga_covered_by, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_intersects <- function(x, y) .Call(wrap__ga_intersects, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_disjoint <- function(x, y) .Call(wrap__ga_disjoint, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_touches <- function(x, y) .Call(wrap__ga_touches, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_crosses <- function(x, y) .Call(wrap__ga_crosses, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_overlaps <- function(x, y) .Call(wrap__ga_overlaps, x, y)

#' @export
#' @rdname topology
#' @family topology
ga_equals_topo <- function(x, y) .Call(wrap__ga_equals_topo, x, y)

#' DE-9IM relationship between geometries
#'
#' Returns the nine character DE-9IM matrix describing how each pair of
#' geometries relates, from which you can derive every named predicate.
#'
#' @details
#' Read the string as the intersections of the interior, boundary and exterior
#' of `x` with those of `y`, in that order. Each character is the dimension of
#' that intersection: `F` for empty, `0` for a point, `1` for a curve, and `2`
#' for a surface. `ga_relate()` returns `NA` for a null geometry on either side.
#'
#' @inheritParams ga_contains
#' @returns a string array of the same length as `x`
#' @export
#' @family topology
#' @references [Relate](https://docs.rs/geo/latest/geo/algorithm/relate/trait.Relate.html)
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' big <- sf::st_polygon(list(
#'   matrix(c(0, 0, 4, 0, 4, 4, 0, 4, 0, 0), ncol = 2, byrow = TRUE)
#' ))
#' x <- geoarrow::as_geoarrow_array(sf::st_sfc(big))
#' y <- geoarrow::as_geoarrow_array(sf::st_sfc(sf::st_point(c(2, 2))))
#'
#' as.vector(ga_relate(x, y))
ga_relate <- function(x, y) .Call(wrap__ga_relate, x, y)

#' Test whether geometries are identical within a tolerance
#'
#' `TRUE` when `x` and `y` have the same type and structure and every
#' coordinate lies within `tolerance` of its counterpart. `ga_equals_exact()`
#' recycles `y` and `tolerance` against `x`.
#'
#' @details
#' Unlike `ga_equals_topo()`, `ga_equals_exact()` compares coordinates in
#' order, so it does not treat a line and its reverse as equal. It measures
#' planar distance between coordinates and returns `NA` for a null on either
#' side.
#'
#' @param x a GeoArrow geometry array
#' @param y a GeoArrow geometry array; length 1 or the same length as `x`
#' @param tolerance the largest planar distance allowed between matching coordinates; length 1 or the same length as `x`
#' @returns a boolean array of the same length as `x`
#' @export
#' @family topology
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' x <- geoarrow::as_geoarrow_array(sf::st_sfc(
#'   sf::st_linestring(rbind(c(0, 0), c(1, 1))),
#'   sf::st_linestring(rbind(c(1, 1), c(0, 0)))
#' ))
#' y <- geoarrow::as_geoarrow_array(sf::st_sfc(
#'   sf::st_linestring(rbind(c(0, 0), c(1, 1.01)))
#' ))
#'
#' # ga_equals_exact() does not treat the reversed line as equal
#' as.vector(ga_equals_exact(x, y, 0.1))
ga_equals_exact <- function(x, y, tolerance = 0) .Call(wrap__ga_equals_exact, x, y, tolerance)

#' Determine the topological dimension of geometries
#'
#' Returns 0 for points, 1 for lines and curves, and 2 for surfaces.
#'
#' @details
#' `ga_dimension()` returns `NA` for an empty geometry, which has no dimension,
#' rather than a point's 0. `ga_boundary_dimension()` gives the dimension of
#' the geometry's boundary instead, so it returns 1 for a polygon and `NA` for
#' a point.
#'
#' @param geometry a GeoArrow geometry array
#' @returns an integer array of the same length as `geometry`
#' @export
#' @rdname ga_dimension
#' @family topology
#' @references [HasDimensions](https://docs.rs/geo/latest/geo/algorithm/dimensions/trait.HasDimensions.html)
#' @examplesIf requireNamespace("sf", quietly = TRUE) && requireNamespace("geoarrow", quietly = TRUE)
#' g <- geoarrow::as_geoarrow_array(sf::st_sfc(
#'   sf::st_point(c(0, 0)),
#'   sf::st_linestring(cbind(c(0, 1), c(0, 1)))
#' ))
#'
#' as.vector(ga_dimension(g))
ga_dimension <- function(geometry) .Call(wrap__ga_dimension, geometry)

#' @export
#' @rdname ga_dimension
#' @family topology
ga_boundary_dimension <- function(geometry) .Call(wrap__ga_boundary_dimension, geometry)

#' Test whether geometries are empty
